FederatedRequestProxy::FederatedRequestProxy(mojo::MessageReceiverWithResponder* receiver)
    : receiver_(receiver) {
}

void FederatedRequestProxy::Abort(
    ) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT0("mojom", "Send blink::mojom::FederatedRequest::Abort");
#endif

  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;

  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::FederatedRequest::kAbort), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::blink::mojom::internal::FederatedRequest_Abort_Params_Data> params(
          message);
  params.Allocate();

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(FederatedRequest::Name_);
  message.set_method_name("Abort");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

// static
bool FederatedRequestStubDispatch::Accept(
    FederatedRequest* impl,
    mojo::Message* message) {
  switch (static_cast<messages::FederatedRequest>(message->header()->name)) {
    case messages::FederatedRequest::kAbort: {
      DCHECK(message->is_serialized());
      internal::FederatedRequest_Abort_Params_Data* params =
          reinterpret_cast<internal::FederatedRequest_Abort_Params_Data*>(
              message->mutable_payload());
      

      // Validation for FederatedRequest.0
      bool success = true;
      FederatedRequest_Abort_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            FederatedRequest::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Abort(        );
      return true;
    }
  }
  return false;
}

// static
bool FederatedRequestStubDispatch::AcceptWithResponder(
    FederatedRequest* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::FederatedRequest>(message->header()->name)) {
    case messages::FederatedRequest::kAbort: {
      break;
    }
  }
  return false;
}
